import{_ as e,o,c as d,a3 as r}from"./chunks/framework.B7pF4b99.js";const b=JSON.parse('{"title":"Motion Prompt 動效設計紀錄","description":"","frontmatter":{"title":"Motion Prompt 動效設計紀錄","outline":[2,3]},"headers":[],"relativePath":"motion-prompt-design-experiment.md","filePath":"motion-prompt-design-experiment.md","lastUpdated":1794377038000}'),a={name:"motion-prompt-design-experiment.md"};function c(i,t,l,s,h,n){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="motion-prompt-動效設計紀錄" tabindex="-1">Motion Prompt 動效設計紀錄 <a class="header-anchor" href="#motion-prompt-動效設計紀錄" aria-label="Permalink to &quot;Motion Prompt 動效設計紀錄&quot;">​</a></h1><p>本頁記錄 WUWAOS 網站改版中<strong>實際使用</strong>的動效：每個效果的 Motion Prompt ID、所在位置、目的、時程／緩動、參考網址。所有效果都遵守同一條界線——<strong>只呈現真實的轉場與狀態，不模擬不存在的 kernel 行為，也不把教學圖說成 QEMU 即時追蹤</strong>。</p><p>動效語彙取自 <a href="https://showheyohtaki.github.io/motion-prompt" target="_blank" rel="noreferrer">Motion Prompt</a>（MIT License，© 2026 Shohei Ohtaki）。每個 ID 對應一個有規格（時程、緩動、距離、角度）的效果；本頁的實作保留這些數字，只替換屬於 WUWAOS 的顏色、文字與元素。</p><h2 id="共用的運動語言" tabindex="-1">共用的運動語言 <a class="header-anchor" href="#共用的運動語言" aria-label="Permalink to &quot;共用的運動語言&quot;">​</a></h2><p>全站共用兩條緩動曲線（來自 Motion Prompt kit），讓所有效果讀起來像同一套系統：</p><table tabindex="0"><thead><tr><th>Token</th><th>值</th><th>用途</th></tr></thead><tbody><tr><td><code>--wuwa-ease-out</code></td><td><code>cubic-bezier(0.22, 1, 0.36, 1)</code></td><td>元素進入、落定（kit <code>eOut</code>）</td></tr><tr><td><code>--wuwa-ease-io</code></td><td><code>cubic-bezier(0.65, 0, 0.35, 1)</code></td><td>對稱的進出、狀態切換（kit <code>eIO</code>）</td></tr><tr><td><code>--wuwa-dur-reveal</code></td><td><code>0.7s</code></td><td>卷動揭示的時程</td></tr><tr><td><code>--wuwa-dur-hover</code></td><td><code>0.3s</code></td><td>懸停回饋的時程</td></tr></tbody></table><h2 id="首頁" tabindex="-1">首頁 <a class="header-anchor" href="#首頁" aria-label="Permalink to &quot;首頁&quot;">​</a></h2><h3 id="_006-typewriter-終端打字" tabindex="-1">#006 Typewriter（終端打字） <a class="header-anchor" href="#_006-typewriter-終端打字" aria-label="Permalink to &quot;#006 Typewriter（終端打字）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>內容</th></tr></thead><tbody><tr><td>位置</td><td><code>HomeTerminal.vue</code> — Hero 右側教學終端</td></tr><tr><td>目的</td><td>讓「輸入 <code>echo hello</code>」這件事有<strong>正在發生</strong>的順序感：先打指令，再出現輸出，最後顯示 U→ecall→S→UART 的邊界。這是全站最長的「主角」動畫，直接點題「從一行 echo hello 看見整套 OS」。</td></tr><tr><td>時程／緩動</td><td>首字 <code>0.3s</code>、每字 <code>0.24s</code>（保留 spec 數字）；每個字由 <code>scale 1.35 → 1</code> 落定（<code>wuwa-type-pop .28s --wuwa-ease-out</code>）；輸出與 stages 分段淡入（<code>.5s</code> / <code>.6s</code>，eOut）。</td></tr><tr><td>保留／替換</td><td>保留 spec 的 <code>0.24s/char</code>、<code>1.35→1</code> 縮放、<code>0.94s</code> 游標明滅週期；把 spec 的「送信按鈕彈出」換成 WUWAOS 的 <code>hello</code> 輸出與邊界 caption。</td></tr><tr><td>參考</td><td><a href="https://showheyohtaki.github.io/motion-prompt/#006" target="_blank" rel="noreferrer">https://showheyohtaki.github.io/motion-prompt/#006</a></td></tr></tbody></table><h3 id="_154-spotlight-終端聚光" tabindex="-1">#154 Spotlight（終端聚光） <a class="header-anchor" href="#_154-spotlight-終端聚光" aria-label="Permalink to &quot;#154 Spotlight（終端聚光）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>內容</th></tr></thead><tbody><tr><td>位置</td><td><code>HomeTerminal.vue</code> — 終端框 <code>.wuwa-console::before</code></td></tr><tr><td>目的</td><td>深色終端上，只把<strong>游標所在的那一小圈</strong>照亮，讓視線跟著指標走；不做整框發光或粒子。這是「pointer 下的位置站出來」，而非裝飾性 glow。</td></tr><tr><td>時程／緩動</td><td><code>radial-gradient(120px circle at var(--spot-x) var(--spot-y))</code>，由 <code>pointermove</code> 直接驅動（無 keyframe，零延遲跟手）；<code>pointerleave</code> 回到預設 <code>50% / 32%</code>。</td></tr><tr><td>保留／替換</td><td>保留「只有游標周圍一圈被照亮」的核心；把 spec 的卡片邊框發光換成終端內的一層表面光（<code>rgba(255,255,255,0.14)</code>）。</td></tr><tr><td>參考</td><td><a href="https://showheyohtaki.github.io/motion-prompt/#154" target="_blank" rel="noreferrer">https://showheyohtaki.github.io/motion-prompt/#154</a></td></tr></tbody></table><h3 id="_074-fade-in-on-scroll-卷動揭示" tabindex="-1">#074 Fade-in on scroll（卷動揭示） <a class="header-anchor" href="#_074-fade-in-on-scroll-卷動揭示" aria-label="Permalink to &quot;#074 Fade-in on scroll（卷動揭示）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>內容</th></tr></thead><tbody><tr><td>位置</td><td><code>index.md</code> 各 <code>[data-reveal]</code> 區塊；邏輯在 <code>composables/useScrollFx.ts</code>（IntersectionObserver，trigger <code>85%</code>）</td></tr><tr><td>目的</td><td>首頁是一條「往下讀」的敘事（Hero → 系統地圖 → 路線 → 實驗室 → 啟動 → 狀態）。區塊依序浮現，把讀者的注意力分段送進下一層，而不是整頁一次出現。</td></tr><tr><td>時程／緩動</td><td><code>opacity 0→1</code> 同時 <code>translateY(28px) → 0</code>，<code>0.7s --wuwa-ease-out</code>（保留 spec 的 28px 位移與 eOut）。</td></tr><tr><td>保留／替換</td><td>保留 spec 的 <code>85%</code> 觸發線、<code>28px</code> 上移、<code>0.7s</code> eOut；用 <code>IntersectionObserver</code> 替換 spec 的演示用卷動軸。</td></tr><tr><td>參考</td><td><a href="https://showheyohtaki.github.io/motion-prompt/#074" target="_blank" rel="noreferrer">https://showheyohtaki.github.io/motion-prompt/#074</a></td></tr></tbody></table><h3 id="_145-timeline-grow-light-學習路線軌道" tabindex="-1">#145 Timeline grow &amp; light（學習路線軌道） <a class="header-anchor" href="#_145-timeline-grow-light-學習路線軌道" aria-label="Permalink to &quot;#145 Timeline grow &amp; light（學習路線軌道）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>內容</th></tr></thead><tbody><tr><td>位置</td><td><code>index.md</code> 學習路線 <code>.wuwa-roadmap</code>；<code>.wuwa-rail-fill</code> 由 <code>useScrollFx</code> 依卷動深度寫 <code>--wuwa-progress</code>，<code>.wuwa-rm-item.is-lit</code> 點亮圓點</td></tr><tr><td>目的</td><td>13 章是一條<strong>時間順序</strong>的學習路徑（Boot → Trap → Process → … → Document）。左側軌道隨著閱讀向下生長、圓點依序點亮，把「讀到第幾層」直接畫出來。</td></tr><tr><td>時程／緩動</td><td>軌道填充 <code>height: var(--wuwa-progress)</code>（卷動驅動，linear 跟手）；圓點 <code>is-lit</code> 切換 <code>0.3s --wuwa-ease-out</code>（背景／邊框變 brand 色）。</td></tr><tr><td>保留／替換</td><td>保留「線往下長、到達的點被填滿」的核心；把 spec 的年份／事件換成章節標題，並讓<strong>卷動向上可逆</strong>（progress 隨卷動雙向更新）。</td></tr><tr><td>參考</td><td><a href="https://showheyohtaki.github.io/motion-prompt/#145" target="_blank" rel="noreferrer">https://showheyohtaki.github.io/motion-prompt/#145</a></td></tr></tbody></table><h3 id="_086-link-underline-章節標題底線" tabindex="-1">#086 Link underline（章節標題底線） <a class="header-anchor" href="#_086-link-underline-章節標題底線" aria-label="Permalink to &quot;#086 Link underline（章節標題底線）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>內容</th></tr></thead><tbody><tr><td>位置</td><td>學習路線 <code>.wuwa-rm-title::after</code>（<code>hover</code> / <code>focus-visible</code> 時）</td></tr><tr><td>目的</td><td>安靜地指出「目前指到哪一章」，不用整卡變色就讓可點擊性被看見。</td></tr><tr><td>時程／緩動</td><td><code>scaleX(0) → scaleX(1)</code>，<code>0.3s --wuwa-ease-out</code>；懸停時 <code>transform-origin: left</code>（由左長出），離開時回到 <code>right</code>（往右縮回）。</td></tr><tr><td>保留／替換</td><td>保留 spec「由左長出、往右縮回」的底線；把橙色換成 brand 色。</td></tr><tr><td>參考</td><td><a href="https://showheyohtaki.github.io/motion-prompt/#086" target="_blank" rel="noreferrer">https://showheyohtaki.github.io/motion-prompt/#086</a></td></tr></tbody></table><h3 id="_081-card-hover-lift-卡片-按鈕懸停" tabindex="-1">#081 Card hover lift（卡片／按鈕懸停） <a class="header-anchor" href="#_081-card-hover-lift-卡片-按鈕懸停" aria-label="Permalink to &quot;#081 Card hover lift（卡片／按鈕懸停）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>內容</th></tr></thead><tbody><tr><td>位置</td><td>Hero 主／次按鈕（<code>translateY(-2px)</code>）、實驗室 entry 卡（<code>translateY(-3px)</code> + 背景提亮）</td></tr><tr><td>目的</td><td>讓按鈕與實驗室入口「看起來可點」；只有指標下的那一個浮起，離開後落回，不做整組同動。</td></tr><tr><td>時程／緩動</td><td><code>0.3s --wuwa-ease-out</code>；lab entry 同時把 CTA 箭頭 <code>translateX(4px)</code> 提示方向。</td></tr><tr><td>保留／替換</td><td>保留「只有懸停的那個輕微浮起＋落回」的核心；用 <code>translateY</code> 替換 spec 的陰影擴張（全站刻意不用重陰影，維持工程圖面感）。</td></tr><tr><td>參考</td><td><a href="https://showheyohtaki.github.io/motion-prompt/#081" target="_blank" rel="noreferrer">https://showheyohtaki.github.io/motion-prompt/#081</a></td></tr></tbody></table><h2 id="全站" tabindex="-1">全站 <a class="header-anchor" href="#全站" aria-label="Permalink to &quot;全站&quot;">​</a></h2><h3 id="_079-scroll-progress-bar-閱讀進度" tabindex="-1">#079 Scroll progress bar（閱讀進度） <a class="header-anchor" href="#_079-scroll-progress-bar-閱讀進度" aria-label="Permalink to &quot;#079 Scroll progress bar（閱讀進度）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>內容</th></tr></thead><tbody><tr><td>位置</td><td><code>style.css</code> <code>.VPDoc::before</code>（<code>@supports (animation-timeline: scroll())</code> 內）</td></tr><tr><td>目的</td><td>長文件（各章節、本頁）讀到幾成，頂端細線由左長到右。純進度指示，無其他含義。</td></tr><tr><td>時程／緩動</td><td><code>transform: scaleX(0→1)</code>，<code>animation-timeline: scroll(root block)</code>（linear，直接等於卷動比例）；<code>3px</code> brand 色。</td></tr><tr><td>保留／替換</td><td>保留 spec「fill = 卷動比例」的核心；用原生 CSS scroll-timeline 實作，<strong>不支援的瀏覽器整段不出現</strong>（無 JS fallback 的跳動）。</td></tr><tr><td>參考</td><td><a href="https://showheyohtaki.github.io/motion-prompt/#079" target="_blank" rel="noreferrer">https://showheyohtaki.github.io/motion-prompt/#079</a></td></tr></tbody></table><h3 id="svg-flow-draw-系統地圖啟動交接" tabindex="-1">SVG flow-draw（系統地圖啟動交接） <a class="header-anchor" href="#svg-flow-draw-系統地圖啟動交接" aria-label="Permalink to &quot;SVG flow-draw（系統地圖啟動交接）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>內容</th></tr></thead><tbody><tr><td>位置</td><td><code>SystemOverview.vue</code> 兩條<strong>實線</strong> boot 路徑 <code>.flow-boot</code>（<code>韌體交接</code>、<code>_start → kernel_main</code>）</td></tr><tr><td>目的</td><td>依 <strong>M → S → U 的真實權限交接方向</strong>畫出啟動流：線由上往下畫出，讓「交接是单向、有次序的」一眼可見。這是資料流的有意義動畫，不是裝飾。</td></tr><tr><td>時程／緩動</td><td><code>pathLength=&quot;1&quot;</code> + <code>stroke-dasharray:1 / stroke-dashoffset:1→0</code>，<code>0.8s --wuwa-ease-out</code>；第二條 delay <code>0.5s</code> 形成次序。</td></tr><tr><td>保留／替換</td><td>用 <code>pathLength=&quot;1&quot;</code> 正規化，讓不同長度的短線都以同一節奏畫出。<strong>虛線的 ecall 邊界不參與線畫</strong>（<code>stroke-dasharray:5 4</code> 會與 draw 衝突），改由下方 #svg-fade 處理。</td></tr><tr><td>參考</td><td>線畫（line-draw）技法；與 #006/#074 同屬 Motion Prompt 的進入類語彙</td></tr></tbody></table><h3 id="svg-fade-in-ecall-權限邊界" tabindex="-1">SVG fade-in（ecall 權限邊界） <a class="header-anchor" href="#svg-fade-in-ecall-權限邊界" aria-label="Permalink to &quot;SVG fade-in（ecall 權限邊界）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>內容</th></tr></thead><tbody><tr><td>位置</td><td><code>SystemOverview.vue</code> 虛線 <code>.flow-call</code>（<code>process_start → U-mode</code>）與所有 <code>.flow-label</code></td></tr><tr><td>目的</td><td>交接畫完後，再淡入「使用者行程 ↔ 核心」的 ecall 邊界與標註——先把啟動方向講完，再講邊界，避免兩種資訊同時爭奪注意力。</td></tr><tr><td>時程／緩動</td><td><code>opacity 0→1</code>，<code>0.6s --wuwa-ease-out</code>，<code>delay 1.3s</code>（兩條 boot 線畫完後）。</td></tr><tr><td>保留／替換</td><td>以淡入替換線畫，因為該邊界是<strong>虛線</strong>，用 dash-offset 會與點線外觀打架；淡入讓虛線保持原樣。</td></tr><tr><td>參考</td><td>與 #074 同屬 fade 語彙</td></tr></tbody></table><h2 id="可近用性與還原-reduced-motion" tabindex="-1">可近用性與還原（reduced motion） <a class="header-anchor" href="#可近用性與還原-reduced-motion" aria-label="Permalink to &quot;可近用性與還原（reduced motion）&quot;">​</a></h2><p>每個效果都有<strong>靜態終端狀態</strong>，在 <code>prefers-reduced-motion: reduce</code> 下全部落定，不卡在中途：</p><ul><li><strong>終端（#006 / #154）</strong>：<code>HomeTerminal.vue</code> 偵測 <code>prefers-reduced-motion</code>，直接把完整 <code>echo hello</code>、<code>hello</code>、stages 全部呈現；聚光停用。</li><li><strong>卷動揭示（#074）</strong>：<code>useScrollFx</code> 在 reduced 下<strong>立即</strong>對所有 <code>[data-reveal]</code> 加 <code>is-revealed</code>，<code>style.css</code> 也强制 <code>[data-reveal]</code> 可見。</li><li><strong>路線軌道（#145 / #086）</strong>：圓點底線與位移過渡在 reduced 下停用；軌道填充保留靜態終端值。</li><li><strong>SVG（flow-draw / fade）</strong>：<code>SystemOverview.vue</code> 在 reduced 下 <code>animation: none</code>，boot 線直接 <code>stroke-dashoffset:0</code>、ecall 邊界 <code>opacity:1</code>。</li><li><strong>閱讀進度（#079）</strong>：<code>.VPDoc::before</code> 在 reduced 下 <code>animation: none</code>。</li><li><strong>實驗室</strong>：四個 lab 元件在 reduced 下把過渡／動畫時程壓到 <code>0.01ms</code>，只保留<strong>狀態的靜態呈現</strong>。</li></ul><p>鍵盤：所有可互動元素（系統圖模組、路線章節、實驗室控制）都有 <code>:focus-visible</code> 外框與 <code>focus-visible</code> 觸發的回饋；終端有 <code>aria-label</code> 說明「教學示意、非即時追蹤」與 sr-only 全文。</p><h2 id="界線聲明-教學圖-qemu-trace" tabindex="-1">界線聲明（教學圖 ≠ QEMU trace） <a class="header-anchor" href="#界線聲明-教學圖-qemu-trace" aria-label="Permalink to &quot;界線聲明（教學圖 ≠ QEMU trace）&quot;">​</a></h2><ul><li>終端與系統地圖都明確標註「<strong>教學示意／依目前 source 繪製的靜態分層</strong>」與「<strong>非 QEMU 即時追蹤</strong>」。</li><li>動效只負責<strong>讓已存在的結構與狀態更清楚</strong>（啟動交接方向、ecall 邊界、卷動進度、目前指到哪一章），不產生任何 OS 沒有資料來源的「即時」訊號。</li><li>實驗室的狀態機（Block Async、FD/OFD、Paging/Swap、Journal）依真實 WUWAOS source 整理；本頁不改變任何狀態模型，只做視覺與資訊階層調整。</li></ul><h2 id="授權" tabindex="-1">授權 <a class="header-anchor" href="#授權" aria-label="Permalink to &quot;授權&quot;">​</a></h2><p>Motion Prompt 效果語彙（ID 與規格數字）取自 <a href="https://showheyohtaki.github.io/motion-prompt" target="_blank" rel="noreferrer">Motion Prompt</a>，<strong>MIT License (c) 2026 Shohei Ohtaki</strong>。各元件的 <code>&lt;style&gt;</code> 區塊保留對應的歸屬註解。</p>',34)])])}const u=e(a,[["render",c]]);export{b as __pageData,u as default};
